update public.items set
  name = $gt$Пінка для вмивання обличчя для всіх типів шкіри$gt$,
  description = $gt$Легка пінка для щоденного вмивання та зняття макіяжу. М’які очищувальні компоненти змивають забруднення, надлишок себуму й навіть водостійку косметику. Після вмивання шкіра залишається чистою та м’якою, без відчуття сухості й стягнутості.

Бетаїн і гліцерин допомагають шкірі утримувати вологу, а пантенол та екстракт алое доповнюють м’яку очищувальну формулу. Пінка підходить для всіх типів шкіри, зокрема сухої та комбінованої.$gt$,
  usage = $gt$Нанесіть невелику кількість пінки на вологу шкіру обличчя. М’яко помасажуйте, приділяючи увагу ділянкам із макіяжем, і ретельно змийте водою. Використовуйте вранці та/або ввечері.$gt$,
  inci = $gt$Aqua, Caffeine, Gluconolactone, Niacinamide, Inulin, Betain, Sodium Cocoamphoacetate, Glycerin, Lauryl Glucoside, Sodium Cocoyl Glutamate, Sodium Lauryl Glucose Carboxylate, Lactic Acid, D-panthenol, Aloe Extract, Chlorophyll, Euxyl PE 9010$gt$,
  warnings = $gt$Для зовнішнього застосування. Уникайте потрапляння в очі. У разі потрапляння ретельно промийте їх водою. За відомої алергії на будь-який компонент утримайтеся від використання. У разі подразнення припиніть застосування.

Термін придатності — 6 місяців із дати виготовлення.$gt$,
  updated_at = now()
where seed_key = 'gt-01' and description is null;

update public.items set
  name = $gt$Ензимна пудра для вмивання$gt$,
  description = $gt$М’яка ензимна пудра для ретельного очищення шкіри. За регулярного використання допомагає зменшити помітність чорних цяток. Підходить для всіх типів шкіри, зокрема тонкої та чутливої. Особливо корисна як додатковий етап очищення для жирної та схильної до висипань шкіри.

Фермент папаїн м’яко відлущує ороговілі клітини, а біла глина (каолін) поглинає надлишок шкірного жиру. Після очищення шкіра стає гладенькою на дотик, лущення менш помітне, а тон виглядає свіжішим і рівнішим.$gt$,
  usage = $gt$Використовуйте 2–3 рази на тиждень. Насипте невелику кількість пудри у вологі долоні та розітріть до утворення легкої пінки. Нанесіть пінку на вологу шкіру обличчя, обережно помасажуйте кінчиками пальців і ретельно змийте водою.$gt$,
  inci = $gt$Kaolin, Sodium Coco Sulfate, Inulin, Papain, Glycine, Allantoin, Camelliae Sinensis Extractum Siccum.$gt$,
  warnings = $gt$Уникайте вдихання сухої пудри та потрапляння засобу в очі. Наносьте на неушкоджену шкіру. За відомої алергії на папаїн або інші компоненти утримайтеся від використання. У разі подразнення припиніть застосування.

Термін придатності — 12 місяців із дати виготовлення.$gt$,
