where seed_key = 'gt-02' and description is null;

update public.items set
  name = $gt$Тонік для нормальної та комбінованої шкіри з гіалуроновою кислотою$gt$,
  description = $gt$Зволожувальний тонік для щоденного догляду за нормальною та комбінованою шкірою. Допомагає прибрати залишки пінки після вмивання та готує шкіру до нанесення сироватки або крему.

Низькомолекулярна гіалуронова кислота допомагає зволожувати роговий шар шкіри, а високомолекулярна утримує вологу на її поверхні. Бетаїн і пантенол пом’якшують шкіру та допомагають зменшити відчуття стягнутості.$gt$,
  usage = $gt$Після вмивання нанесіть тонік на спонж і м’яко протріть ним шкіру обличчя та шиї. Не змивайте.$gt$,
  inci = $gt$Aqua, Betain, Gluconolactone, D-panthenol, Hydrolyzed Wheat Protein, Urea pura, Aloe Extract, Sodium Hyaluronate 10-100 kDa, Sodium Hyaluronate 2000 kDa, Euxyl PE 9010$gt$,
  warnings = $gt$Для зовнішнього застосування. Уникайте потрапляння в очі. Тонік містить гідролізований білок пшениці. За відомої алергії на будь-який компонент утримайтеся від використання. У разі подразнення припиніть застосування.

