update public.items set
  name = $gt$Тонік для сухої шкіри з гіалуроновою кислотою$gt$,
  description = $gt$Тонік завершує етап очищення: допомагає прибрати залишки пінки після вмивання та готує шкіру до нанесення сироватки або крему. Підходить для сухої та зневодненої шкіри, особливо якщо після вмивання відчувається стягнутість.

Формула містить два види гіалуронової кислоти. Низькомолекулярна допомагає зволожувати роговий шар шкіри, а високомолекулярна утримує вологу на її поверхні. Бетаїн, трегалоза та гліцерин доповнюють зволожувальну дію й допомагають повернути шкірі м’якість.$gt$,
  usage = $gt$Після вмивання нанесіть тонік на спонж і м’яко протріть ним шкіру обличчя та шиї. Не змивайте.$gt$,
  inci = $gt$Aqua, Betain, Trehalose, Glycerine, Gluconolactone, D-panthenol, Hydrolyzed Wheat Protein, Urea pura, Aloe Extract, Sodium Hyaluronate 10-100 kDa, Sodium Hyaluronate 2000 kDa, Euxyl PE 9010$gt$,
  warnings = $gt$Для зовнішнього застосування. Уникайте потрапляння в очі. Тонік містить гідролізований білок пшениці. За відомої алергії на будь-який компонент утримайтеся від використання. У разі подразнення припиніть застосування.

