update public.items set
  name = $gt$Тонік з пребіотиком для проблемної шкіри з висипаннями$gt$,
  description = $gt$Тонік для шкіри, схильної до висипань, чорних цяток і жирного блиску. Завершує очищення після вмивання, допомагає прибрати залишки пінки та готує шкіру до нанесення сироватки або крему.

Саліцилова кислота сприяє відлущуванню ороговілих клітин у порах, завдяки чому чорні цятки стають менш помітними. Цинк PCA та ніацинамід допомагають зменшити жирний блиск. Пребіотик інулін підтримує природну мікрофлору шкіри, а трегалоза та пантенол допомагають зберегти її зволоженою та м’якою.$gt$,
  usage = $gt$Після вмивання нанесіть тонік на спонж і м’яко протріть ним обличчя, оминаючи ділянки навколо очей і губ. Не змивайте.$gt$,
  inci = $gt$Aqua, Zinc PCA, Salicylic Acid, Trehalose, Niacinamide, Inulin, Gluconolactone, D-panthenol, Chlorophyll, Euxyl PE 9010$gt$,
  warnings = $gt$Для зовнішнього застосування. Уникайте потрапляння в очі та нанесення на пошкоджену або подразнену шкіру. За відомої алергії на саліцилову кислоту чи інші компоненти утримайтеся від використання. У разі подразнення припиніть застосування.

