update public.items set
  name = $gt$Сироватка для обличчя «Глибоке зволоження»$gt$,
  description = $gt$Зволожувальна сироватка з ліфтинг-ефектом. Завдяки зволоженню шкіра виглядає більш пружною та підтягнутою, а дрібні зморшки, які підкреслює сухість, стають менш помітними.

У формулі поєднано два види гіалуронової кислоти. Низькомолекулярна допомагає зволожити роговий шар шкіри, а високомолекулярна утворює на поверхні тонку невидиму плівку, яка допомагає утримувати вологу. Бетаїн і комплекс Aquaxyl доповнюють зволожувальну дію. Сироватка підійде, якщо після вмивання шкіру стягує або їй бракує пружності.$gt$,
  usage = $gt$Після вмивання або тоніка нанесіть кілька крапель сироватки на злегка вологу шкіру обличчя та шиї. М’яко розподіліть кінчиками пальців, а потім нанесіть крем.$gt$,
  inci = $gt$Aqua, Betain, Sodium Hyaluronate 10-100 kDa, Sodium Hyaluronate 2000 kDa, Aquaxyl, Hydrolyzed Wheat Protein, Hydrolyzed Collagen, Aloe Extract, Ammonium Acryloyldimethyltaurate/VP Copolymer, Xanthan Gum, Euxyl PE 9010$gt$,
  warnings = $gt$Для зовнішнього застосування. Уникайте потрапляння в очі. Сироватка містить гідролізований білок пшениці. За відомої алергії на будь-який компонент утримайтеся від використання. У разі подразнення припиніть застосування.

