update public.items set
  name = $gt$Сироватка з вітаміном С та ніацинамідом$gt$,
  description = $gt$Сироватка для шкіри з нерівним тоном, пігментними плямами та темними слідами після висипань. Вітамін С і ніацинамід допомагають поступово освітлювати ці ділянки, щоб тон ставав рівнішим, а шкіра виглядала свіжішою.

Вітамін С забезпечує антиоксидантний захист і підтримує природне утворення колагену. Це робить сироватку вдалим вибором для антивікового догляду, коли шкіра втрачає пружність і стають помітнішими дрібні зморшки. Ніацинамід підтримує захисний бар’єр шкіри й допомагає зменшити видиме почервоніння навколо висипань. Гліцерин і пантенол зволожують, а сквалан та олія жожоба пом’якшують шкіру.$gt$,
  usage = $gt$Нанесіть невелику кількість сироватки на очищену шкіру обличчя вранці та/або ввечері, перед кремом. Завершуйте ранковий догляд сонцезахисним засобом із SPF.$gt$,
  inci = $gt$Aqua, Glycerin, D-panthenol, Niacinamide, AMITOSE DGA, Squalane, Jojoba Oil, Tocopheryl Acetate, Olivem 1000, Euxyl K 100$gt$,
  warnings = $gt$Для зовнішнього застосування. Уникайте потрапляння в очі. За відомої алергії на будь-який компонент утримайтеся від використання. У разі подразнення припиніть застосування.

Зберігання — у темному прохолодному місці.
