update public.items set
  name = $gt$Пептидна сироватка для шкіри навколо очей$gt$,
  volume = $gt$10 мл$gt$,
  description = $gt$В основі сироватки — комплекс пептидів, кофеїну та ніацинаміду для догляду за шкірою навколо очей. Кофеїн і пептиди допомагають зменшити видимість ранкової припухлості. Ніацинамід допомагає вирівняти тон шкіри під очима й зробити темні кола, пов’язані з пігментацією, менш помітними.

Пептид Acetyl Hexapeptide-8 доповнює догляд за шкірою з дрібними мімічними зморшками. Гліцерин і комплекс Aquaxyl допомагають утримувати вологу, тому шкіра виглядає гладенькою, а дрібні лінії від сухості стають менш помітними.$gt$,
  usage = $gt$Наносьте невелику кількість сироватки на чисту суху шкіру навколо очей вранці та/або ввечері. Делікатно розподіліть подушечками пальців, уникаючи лінії вій. Підходить для щоденного використання.$gt$,
  inci = $gt$Aqua (Water), Glycerin, Hesperidin Methyl Chalcone, Steareth-20, Dipeptide-2, Palmitoyl Tetrapeptide-7, Acetyl Hexapeptide-8, Niacinamide, Aquaxyl, Hydrolyzed Wheat Protein, Hydrolyzed Collagen, Caffeine, Aloe Barbadensis Leaf Juice, Ammonium Acryloyldimethyltaurate, Xanthan Gum, Ethylhexylglycerin.$gt$,
  warnings = $gt$Для зовнішнього застосування. Уникайте потрапляння в очі. Сироватка містить гідролізований білок пшениці. За відомої алергії на будь-який компонент утримайтеся від використання. У разі подразнення припиніть застосування.

