update public.items set
  name = $gt$Живильний крем для обличчя$gt$,
  description = $gt$Насичений крем для щоденного живлення сухої шкіри та антивікового догляду, якій бракує м’якості та еластичності. Особливо доречний у холодну пору року, коли шкіра швидше втрачає вологу й частіше відчувається стягнутість.

Масло ши, кокосова олія, ланолін і сквалан пом’якшують шкіру та допомагають зменшити втрату вологи. Бетаїн, гліцерин і трегалоза підтримують зволоження. Шкіра стає м’якшою й гладенькою на дотик, а дрібні зморшки, які підкреслює сухість, виглядають менш помітними. Крем підійде і для щоденного догляду за зрілою шкірою, схильною до сухості.$gt$,
  usage = $gt$Нанесіть невелику кількість крему на очищену шкіру обличчя та шиї. М’яко розподіліть, приділяючи особливу увагу сухим ділянкам. Якщо користуєтеся сироваткою, наносьте крем після неї.$gt$,
  inci = $gt$Aqua, Shea Butter, Coconut Oil RBD, Stearic Acid, Grapeseed Oil, Jojoba Oil, Peach Kernel Oil, Lanolin, Cetyl Palmitate, OleoSoft-4, Caprylic Triglyceride, Olivem 1000, Squalane, Betaine, Glycerine, Aquaxyl, Trehalose, Tocopheryl Acetate, D-panthenol, Euxyl PE 9010.$gt$,
  warnings = $gt$Для зовнішнього застосування. Уникайте потрапляння в очі. Крем містить ланолін. За відомої алергії на ланолін або інші компоненти утримайтеся від використання. У разі подразнення припиніть застосування.

Термін придатності — 6 місяців із дати виготовлення.$gt$,
  updated_at = now()
where seed_key = 'gt-12' and description is null;

update public.items set
  name = $gt$Універсальний зволожувальний крем$gt$,
  description = $gt$Щоденний крем для тих, хто любить відчуття м’якої, зволоженої шкіри й легкі текстури. Він швидко вбирається, тому зручний для ранкового догляду. Підходить для всіх типів шкіри, зокрема для комбінованої, коли щокам бракує вологи, а для Т-зони хочеться чогось легкого.

Бетаїн і комплекс Aquaxyl допомагають утримувати вологу та зменшувати відчуття стягнутості після вмивання. Олії виноградних і персикових кісточок, жожоба та зародків пшениці пом’якшують шкіру й роблять її гладенькою на дотик.$gt$,
  usage = $gt$Нанесіть невелику кількість крему на очищену шкіру обличчя та шиї. Якщо користуєтеся сироваткою, наносьте крем після неї.$gt$,
  inci = $gt$Aqua, Betaine, Aquaxyl, Grapeseed Oil, Wheatgerm Oil, Peach Kernel Oil, Jojoba Oil, Olivem 1000, Caprylic Triglyceride, Hydrolyzed Wheat Protein, D-panthenol, Tocopheryl Acetate, Euxyl PE 9010$gt$,
  warnings = $gt$Для зовнішнього застосування. Уникайте потрапляння в очі. Крем містить олію зародків пшениці та гідролізований білок пшениці. За відомої алергії на будь-який компонент утримайтеся від використання. У разі подразнення припиніть застосування.

Термін придатності — 6 місяців із дати виготовлення.$gt$,
