update public.items set
  name = $gt$Крем для проблемної шкіри з висипаннями$gt$,
  description = $gt$Легкий крем для жирної та комбінованої шкіри, схильної до висипань. Швидко вбирається й не залишає жирного блиску. Підійде, якщо протягом дня починають блищати лоб, ніс і підборіддя, а після вмивання шкіру стягує.

Ніацинамід і комплекс Evermat допомагають регулювати виділення себуму, щоб жирний блиск був менш помітним. Бетаїн і сечовина допомагають шкірі утримувати вологу, а пантенол пом’якшує її. Формулу доповнюють глюконолактон, оксид цинку та екстракти розмарину й шавлії.$gt$,
  usage = $gt$Нанесіть невелику кількість крему на очищену шкіру обличчя та рівномірно розподіліть. Якщо користуєтеся тоніком, наносьте крем після нього. Для захисту від сонця використовуйте окремий засіб із SPF.$gt$,
  inci = $gt$Aqua, Betain, Peach Kernel Oil, Sweet Almond Oil, Caprylic Triglyceride, Olivem 1000, Lannet O, Zinc Oxide, Gluconolactone, Niacinamide, Urea Pura, Methylsulfonylmethane, Evermat, SC-CO2 Rosmarinus Officinalis Extract, SC-CO2 Salvia Officinalis Leaf Extract, Tocopheryl Acetate, D-panthenol, Euxyl PE 9010.$gt$,
  warnings = $gt$Для зовнішнього застосування. Уникайте потрапляння в очі. Крем містить олію солодкого мигдалю. За відомої алергії на будь-який компонент утримайтеся від використання. У разі подразнення припиніть застосування.

