update public.items set
  name = $gt$Зволожувальний матуючий крем для жирної шкіри$gt$,
  description = $gt$Легкий крем-емульсія для щоденного зволоження жирної шкіри. Його шовковиста текстура легко розподіляється й залишає м’який матовий фініш. Особливо підійде, якщо протягом дня починають блищати лоб, ніс і підборіддя.

Активний фітокомплекс Evermat допомагає регулювати виділення себуму, зменшувати жирний блиск і робити пори візуально менш помітними. Бетаїн і комплекс Aquaxyl допомагають шкірі утримувати вологу. Формулу доповнюють ніацинамід, олія рисових висівок та екстракти розмарину й шавлії.$gt$,
  usage = $gt$Нанесіть невелику кількість крему-емульсії на очищену шкіру обличчя та рівномірно розподіліть. Якщо користуєтеся сироваткою, наносьте крем після неї.$gt$,
  inci = $gt$Aqua, Evermat, Betain, Aquaxyl, Niacinamide, Montanov 202, Lanol P, Rice Bran Oil, SC-CO2 Rosmarinus Officinalis Extract, SC-CO2 Salvia Officinalis Leaf Extract, Tocopheryl Acetate, Euxyl PE 9010.$gt$,
  warnings = $gt$Для зовнішнього застосування. Уникайте потрапляння в очі. За відомої алергії на будь-який компонент утримайтеся від використання. У разі подразнення припиніть застосування.

