update public.items set
  name = $gt$Крем з бакучіолом$gt$,
  description = $gt$Антивіковий крем із бакучіолом підходить і для сухої шкіри, особливо якщо поряд із сухістю турбують дрібні зморшки, втрата пружності або нерівний тон. Бакучіол — рослинний компонент із ретинолоподібною дією. За регулярного використання він допомагає зробити зморшки й пігментні плями менш помітними, а шкіра виглядає гладенькою та пружнішою.

Низькомолекулярна гіалуронова кислота, бетаїн і гліцерин допомагають утримувати вологу. Масло ши й олії макадамії, жожоба та виноградних кісточок пом’якшують суху шкіру. Крем можна використовувати цілий рік, зокрема влітку.$gt$,
  usage = $gt$Наносьте невелику кількість крему на очищену шкіру обличчя та шиї вранці та/або ввечері. Якщо користуєтеся сироваткою, наносьте крем після неї. Вранці завершуйте догляд сонцезахисним засобом із SPF.$gt$,
  inci = $gt$Aqua, Bakuchiol, Betain, Aquaxyl, Sodium Hyaluronate 10-100 kDa, Grapeseed Oil, Macadamia Nut Oil, Jojoba Oil, Shea Butter, OleoSoft-4, Olivem 1000, Cetyl Palmitate, Lannet O, Caprylic Triglyceride, Hydrolyzed Wheat Protein, D-panthenol, Tocopheryl Acetate, Glycerine, Euxyl PE 9010.$gt$,
  warnings = $gt$Для зовнішнього застосування. Уникайте потрапляння в очі. Крем містить гідролізований білок пшениці та олію макадамії. За відомої алергії на будь-який компонент утримайтеся від використання. У разі подразнення припиніть застосування.

