update public.items set
  name = $gt$Крем із ботокс-ефектом$gt$,
  description = $gt$Крем із пептидом Argireline поєднує догляд за мімічними зморшками з ліфтинг-ефектом. За регулярного використання допомагає зробити мімічні лінії на лобі та між бровами менш помітними. Шкіра виглядає гладенькою, більш пружною та підтягнутою.

